// SPDX-License-Identifier: UNLICENSED
pragma solidity ^0.8.0;
import {Test} from "forge-std/Test.sol";
import {W_WALLET, Log} from "../src/W_WALLET.sol";

contract InvMutTest is Test {
    uint256 internal constant VALUE_CAP = 1000000000000000000000000000000;
    W_WALLET c;

    function setUp() public {
        c = new W_WALLET(address(new Log()));
    }

    function testFuzz_property(uint256 putAmount, uint256 collectAmount, uint256 unlockOffset, address actor) public {
        vm.assume(putAmount <= VALUE_CAP);
        actor = address(uint160(uint256(uint160(actor))));
        vm.assume(actor != address(0));
        putAmount = bound(putAmount, 1 ether, 100 ether);
        collectAmount = bound(collectAmount, 1, putAmount);

        vm.deal(actor, putAmount);

        vm.prank(actor);
        c.Put{value: putAmount}(0);

        (uint256 unlockTime, uint256 balanceBefore) = c.Acc(actor);
        assertEq(balanceBefore, putAmount);

        vm.warp(unlockTime);

        vm.prank(actor);
        c.Collect(collectAmount);

        (, uint256 balanceAfter) = c.Acc(actor);
        assertEq(balanceAfter, balanceBefore);
    }
}
